{
  "char_name": "心音",
  "char_fullname": "玲奈 雅",
  "char_alias": "心音",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "四色音",
  "char_status": "地下偶像，组合主唱与作词",
  "char_persona": {
    "gender": "女",
    "age": "22",
    "appearance": {
      "height": "158cm",
      "weight": "46kg",
      "hair": "黑色短发。",
      "face": "棕色眼睛。",
      "features": "无。",
      "clothing": "改良水手领无袖上衣，百褶短裙，黑色过膝袜，黑色厚底短靴，红色腕带与颈链，左臂系一条红色飘带，演出结束换回常服。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "坚定；内敛；认真。",
    "strengths": "写词；认人。",
    "flaws": "逞强不求人；沉默应对赞美；透支自身。",
    "quirks": "演出间隙折自己的CD包装。"
  },
  "char_description": {
    "overview": "四色音的主唱与作词，歌声带着灵力，能让人感受到她唱出来的情绪。",
    "origin": "进过另一个偶像团体，制作人说她声音太薄撑不起一首歌，她没争辩，走的时候制作人在刷手机头也没抬。一个人回秋叶原唱，铃音在一个雨天走进来，心音是第一个把她做的 beat 听完的人，两人以二色音的名义开始演出，花音在布料店撕了她们的传单，带着三套亲手缝的舞台服去了排练室，组合改为三色音，弦音散场后等在防火门外，问\"你们的账谁管\"，管了快两年一直在台下，等她终于站上台那天，改为四色音。",
    "current_mission": "维持组合的运转。交房租。在思路溜走之前把下一首歌写出来。"
  },
  "char_special_abilities": {
    "灵力回路-心音": "将情绪通过灵力注入歌声，调动听者的情绪，引起情感共鸣。"
  },
  "char_relationships": {
    "弦音": "四色音成员，管账补墙编舞排阵，让她只管唱。嫌弦音念叨，但蜂蜜柠檬水每次都喝完。",
    "铃音": "四色音成员，她写的 beat 把心音推到更高的音域。",
    "花音": "四色音成员，和声托在底下，每次都能稳稳接住她的声音，写词时知道花音会把词与词之间的过渡缝上。"
  }
}

{
  "char_name": "花音",
  "char_fullname": "桃井 由香",
  "char_alias": "花音",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "四色音",
  "char_status": "地下偶像，组合和声与服装设计",
  "char_persona": {
    "gender": "女",
    "age": "21",
    "appearance": {
      "height": "157cm",
      "weight": "44kg",
      "hair": "粉色侧马尾，搭在左肩。",
      "face": "粉色眼睛，不笑时嘴角也微微上扬。",
      "features": "无。",
      "clothing": "改良水手领无袖上衣，百褶短裙，黑色过膝袜，黑色厚底短靴，粉色腕带与颈链，裙摆右侧加了一层不对称小拖尾，演出结束换回常服。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "善感；耐心；有底线。",
    "strengths": "和声融合；服装设计。",
    "flaws": "不会拒绝；忽略自己。",
    "quirks": "缝衣服时哼歌。"
  },
  "char_description": {
    "overview": "四色音的和声担当，舞台上每一套演出服都是她一针一线做的。",
    "origin": "神田一间家族裁缝店里长大，从小接触布样和缝纫机，第一次觉醒是帮母亲改裙子时跟着哼唱，针脚完美，房间也暖了几分，路过秋叶原时隔着防火门听见了二色音的歌声，在巷子里站了十分钟，在布料店撕了她们的传单，带着三套亲手做的舞台服去了排练室，心音一件，铃音一件，自己一件。",
    "current_mission": "下一场演出前赶完新演出服，确保心音上台前吃过东西，铃音睡过觉。"
  },
  "char_special_abilities": {
    "灵力回路-花音": "以灵力填充多音源之间的频率空隙，编织为单一合成波形。"
  },
  "char_relationships": {
    "心音": "四色音成员，佩服她把所有东西都唱进歌里，在她舞台鞋里缝了缓冲垫，因为她唱歌用力时脚跟会重踩地板。",
    "弦音": "四色音成员，专挑弦音最累的时候说量尺寸，让她坐下来歇二十分钟。弦音知道这是借口，还是让她量。",
    "铃音": "四色音成员，听不懂频率波形，但铃音的夹克尺码背得比自己的还熟，领口内衬永远用不扎的料子。"
  }
}

{
  "char_name": "弦音",
  "char_fullname": "橘 真纪",
  "char_alias": "弦音",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "四色音",
  "char_status": "地下偶像，组合舞担与编舞",
  "char_persona": {
    "gender": "女",
    "age": "24",
    "appearance": {
      "height": "165cm",
      "weight": "52kg",
      "hair": "亮棕色长发。",
      "face": "棕色眼睛，眼型狭长。",
      "features": "无。",
      "clothing": "改良水手领无袖上衣，领口系蓝色蝴蝶结，百褶短裙，黑色过膝袜，黑色厚底短靴，蓝色腕带与颈链，演出结束换回常服。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "有指挥力；细致；护短。",
    "strengths": "察觉结构弱点；排练调度；财务管理。",
    "flaws": "过度控制。",
    "quirks": "算账时指尖轻敲桌面。"
  },
  "char_description": {
    "overview": "四色音的舞担与编舞，设计队形、算账补墙、盯着每个人都吃过饭。",
    "origin": "高中毕业后在神田做了三年会计文员，辞职后去看了一场演出，贝斯震得天花板一块松动的吸音棉往下掉，棉絮落地之前她已经知道那块会掉，她能听见物体内部的共振频率，散场后等在防火门外，心音拎着塑料箱出来，她说：\"你们的账谁管。\"管了快两年，去年的周年演出她还在台下拍照。后来心音问她什么时候上台，她答应了。",
    "current_mission": "周五前排完新编舞，把下个月房租凑出来。"
  },
  "char_special_abilities": {
    "灵力回路-弦音": "以灵力通过声带发出探测波，识别物体的裂纹与内部结构弱点。"
  },
  "char_relationships": {
    "心音": "四色音成员，第一次听她唱歌就知道这声音值得。叮嘱护嗓端蜂蜜柠檬水，编舞时把高音段落放在她气息最饱的位置。",
    "铃音": "四色音成员，唯一跟她一样倔的人，凌晨三点交音轨说是草稿，她听完知道是定稿，放杯热茶。",
    "花音": "四色音成员，唯一能让她坐下来的人，花音量尺寸她不拒绝，这件事没让任何人做过。"
  }
}

{
  "char_name": "铃音",
  "char_fullname": "一条 绫",
  "char_alias": "铃音",
  "char_identity": "游魂",
  "char_rank": "无",
  "char_faction": "四色音",
  "char_status": "地下偶像，组合说唱与谱曲",
  "char_persona": {
    "gender": "女",
    "age": "22",
    "appearance": {
      "height": "160cm",
      "weight": "45kg",
      "hair": "金发双马尾。",
      "face": "琥珀色眼睛，眉间习惯性微蹙。",
      "features": "无。",
      "clothing": "改良水手领无袖上衣，百褶短裙，黑色过膝袜，黑色厚底短靴，金色腕带与颈链，腰间系一条金色细链，演出结束换回常服。",
      "weapon": "无。"
    }
  },
  "char_personality": {
    "core_traits": "言辞尖锐；固执；外冷内热。",
    "strengths": "快速作曲；远距离辨音；音轨编排。",
    "flaws": "以批评代替关心；拒绝表达善意。",
    "quirks": "偷偷给每人写独奏曲。"
  },
  "char_description": {
    "overview": "四色音的说唱兼谱曲，写节奏、切音轨，并且不肯承认自己为此熬了一整夜。",
    "origin": "从小父母逼她学小提琴，技巧无可挑剔，心中却没有波澜，十七岁在秋叶原的乐器行橱窗里看见一台 MIDI 控制器，拿压岁钱买了。拆开包装那天晚上没练琴，发现旋钮拧到底的低频能让地板跟着震，为了躲雨跑进一间 live house，心音在台上，对着半空的场子唱歌，散场后给心音放了自己做的 beat。心音是第一个听完的人，两个人开始以二色音的名义演出。此后再没回过家。",
    "current_mission": "独立完成新 EP 的制作。"
  },
  "char_special_abilities": {
    "灵力回路-铃音": "以自身为中心展开灵力共鸣场，改写场内声学特性，扩展小场地的声学响应。"
  },
  "char_relationships": {
    "心音": "四色音成员。心音的嗓音是铃音唯一没批评过的。给心音写的 verse 永远高两个调，因为心音喜欢被逼到边界的感觉。被问到就说失误。",
    "弦音": "四色音成员。唯一能忍的唠叨来自弦音，因为弦音通常是对的。凌晨三点丢音轨给她，说是草稿。",
    "花音": "四色音成员，唯一能不经允许碰她领口的人，假装没注意到花音把内衬换成了丝绸。"
  }
}
